INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('angle_arcs_are_the_only_vg_object_kind_never_stamped_so_no_mechanism_can_address_one_by_its_authored_id', 'Every vg object kind carries its authored id in userData.vgId except angle arcs — lines, planes, normals, points, segments and vectors are all stamped, the arc loop is not — so a glow, a focal id or any future emphasis that names an arc resolves to nothing and fails silently', 'MODERATE', 'peter_parker:field3d_surgeon', 'In updateVectorGeometry3DFrame (src/lib/renderers/field_3d_renderer.ts) the display pass stamps every pool it fills: lines at ~15003 (stamp(m, L.id) plus label and dir arrow), planes and their normals at ~15026 (stamp(qm, P.id), stamp(pn, P.id + ".normal")), points at ~15060, segments at ~15078, vectors at ~15092. THE ARC LOOP AT ~15106-15129 HAS NO stamp() CALL AT ALL — it writes geometry and sets visible, and the mesh keeps only its pool identity ("vg_lp_arc_" + i) from build time. stamp() is one line (m.userData.vgId = id), so an arc is the single kind of authored vg object that cannot be found by the id its author gave it. WHY IT IS ONLY LATENT TODAY: scanned all 96 field_3d concepts — ZERO sentences glow an arc id, so nothing is currently broken. The only references are lines_and_planes_in_space STATE_6 focal_primitive_id = "arc1" and STATE_7 = "arc_normal", and focal_primitive_id has no renderer consumer (it feeds smoke_visual_validator''s paid vision prompt, which passes the string through and never resolves it against the scene). WHY IT IS A TRAP RATHER THAN A CURIOSITY: an arc is exactly what an author reaches for when the taught thing IS the angle, which is precisely when they will write glow: "arc_normal". applyGlowEmphasis then dims every peer to 0.4 and brightens nothing, because the named object cannot be found — the C-1 signature (bug_class: a glow whose target is absent dims the scene with no focal). The author sees a state that dims for no reason, with nothing in the JSON obviously wrong, and no gate fires: THE EYE has no check that a glow target resolves, and the concept validator does not cross-check glow ids against the vg object set. The corrected record for the P3 this came from: focal_primitive_id is NOT unconsumed. It is read by src/scripts/smoke_visual_validator.ts (extractFocalPrimitiveIds, ~:48-57) and shipped as focal_primitive_ids to the paid gate. Its two arc-valued entries are SEMANTICALLY CORRECT and must not be repointed at a stamped but wrong object merely to make them resolvable.', 'EVERY POOL THE DISPLAY PASS FILLS GETS stamp()ed WITH ITS AUTHORED ID, WITHOUT EXCEPTION. An addressing scheme with one unaddressable kind is worse than none, because it is invisible: the author uses the same syntax that works everywhere else and gets silence. AND THE GENERAL FORM: WHEN A SYSTEM LETS AUTHORS REFER TO OBJECTS BY NAME, THE SET OF NAMEABLE OBJECTS MUST BE CLOSED AND CHECKED. A name that resolves to nothing must fail LOUDLY at validate time, not degrade into a silent no-op at render time — a validator cross-check of every authored glow / focal / widget target against the state''s own vg object set costs nothing and turns this whole class into a build error.', 'js_eval', 'TWO checks, and the second is the one that generalises. (1) ENGINE: after a vg display pass, assert that for every authored object in points, lines, angle_arcs, intersections, segments, vectors and planes there exists a visible mesh whose userData.vgId equals that authored id. Today the arc entries fail and every other kind passes — which is the discriminating result, not a general "objects render" assertion. (2) AUTHORING (cheaper, and catches the real-world case): for every state, collect the vg object id set and assert that every sentence glow, every focal_primitive_id and every widget target is a member. FAIL on any name that resolves to nothing. Run over the fleet this reports 0 failures today and would have reported the first arc-glow the day it was authored. NEGATIVE CONTROL: author glow: "arc_normal" on lines_and_planes_in_space STATE_7 s7_2 and confirm check (2) FAILS while the rendered frame shows the scene dimmed to 0.4 with no focal — the C-1 signature — proving the probe catches the silent case rather than restating the reveal gate.', 'OPEN', ARRAY['lines_and_planes_in_space']::text[], ARRAY[]::text[], 'session_2026-08-27_p3_grading', 'incident', NULL)
ON CONFLICT (bug_class) DO UPDATE SET
  title = EXCLUDED.title,
  severity = EXCLUDED.severity,
  owner_cluster = EXCLUDED.owner_cluster,
  root_cause = EXCLUDED.root_cause,
  prevention_rule = EXCLUDED.prevention_rule,
  probe_logic = EXCLUDED.probe_logic,
  status = EXCLUDED.status,
  concepts_affected = EXCLUDED.concepts_affected,
  fixed_in_files = EXCLUDED.fixed_in_files,
  fixed_at = EXCLUDED.fixed_at
WHERE engine_bug_queue.root_cause NOT LIKE '%THE ARC LOOP AT ~15106-15129 HAS NO stamp() CALL AT ALL%'
  AND engine_bug_queue.status NOT IN ('FIXED', 'FALSE_POSITIVE');

-- Provenance repair: a protected row is never overwritten, but a NULL
